CREATE TABLE IF NOT EXISTS public.appointment_recurrence_patterns ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES public.hospitals(id) ON DELETE CASCADE, appointment_id UUID NOT NULL REFERENCES public.appointments(id) ON DELETE CASCADE, pattern_type TEXT NOT NULL CHECK (pattern_type IN ('daily', 'weekly', 'bi_weekly', 'monthly', 'custom')), recurrence_rule JSONB NOT NULL DEFAULT '{}', start_date DATE NOT NULL, end_date DATE, max_occurrences INTEGER, exceptions JSONB DEFAULT '[]'::jsonb, created_by UUID NOT NULL REFERENCES public.profiles(id), created_at TIMESTAMP WITH TIME ZONE DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(), updated_by UUID REFERENCES public.profiles(id) ); ALTER TABLE public.appointment_recurrence_patterns ENABLE ROW LEVEL SECURITY; CREATE INDEX IF NOT EXISTS idx_recurrence_hospital_id ON public.appointment_recurrence_patterns(hospital_id); CREATE INDEX IF NOT EXISTS idx_recurrence_appointment_id ON public.appointment_recurrence_patterns(appointment_id); CREATE INDEX IF NOT EXISTS idx_recurrence_start_date ON public.appointment_recurrence_patterns(start_date); CREATE POLICY "Hospital staff can view recurrence patterns" ON public.appointment_recurrence_patterns FOR SELECT USING ( hospital_id IN ( SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid() UNION SELECT hospital_id FROM public.patients WHERE user_id = auth.uid() ) ); CREATE POLICY "Hospital staff can create recurrence patterns" ON public.appointment_recurrence_patterns FOR INSERT WITH CHECK ( hospital_id IN (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid()) AND created_by = auth.uid() ); CREATE POLICY "Hospital staff can update recurrence patterns" ON public.appointment_recurrence_patterns FOR UPDATE USING ( hospital_id IN (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid()) ) WITH CHECK ( hospital_id IN (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid()) ); CREATE POLICY "Hospital staff can delete recurrence patterns" ON public.appointment_recurrence_patterns FOR DELETE USING ( hospital_id IN (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid()) ); ALTER TABLE public.appointments ADD COLUMN IF NOT EXISTS attended_at TIMESTAMP WITH TIME ZONE, ADD COLUMN IF NOT EXISTS attended_by UUID REFERENCES public.profiles(id), ADD COLUMN IF NOT EXISTS no_show_flagged_at TIMESTAMP WITH TIME ZONE, ADD COLUMN IF NOT EXISTS follow_up_contact_sent BOOLEAN DEFAULT FALSE; CREATE TABLE IF NOT EXISTS public.appointment_no_shows ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), hospital_id UUID NOT NULL REFERENCES public.hospitals(id) ON DELETE CASCADE, appointment_id UUID NOT NULL REFERENCES public.appointments(id) ON DELETE CASCADE, reason_code TEXT NOT NULL CHECK (reason_code IN ('no_show', 'cancelled', 'rescheduled', 'completed')), follow_up_status TEXT DEFAULT 'pending' CHECK (follow_up_status IN ('pending', 'sent', 'ignored', 'resolved')), follow_up_notes TEXT, flagged_by UUID NOT NULL REFERENCES public.profiles(id), flagged_at TIMESTAMP WITH TIME ZONE DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE DEFAULT now(), patient_notified_at TIMESTAMP WITH TIME ZONE, patient_notification_channel TEXT CHECK (patient_notification_channel IN ('email', 'sms', 'push', 'app')) ); ALTER TABLE public.appointment_no_shows ENABLE ROW LEVEL SECURITY; CREATE INDEX IF NOT EXISTS idx_no_shows_hospital_id ON public.appointment_no_shows(hospital_id); CREATE INDEX IF NOT EXISTS idx_no_shows_appointment_id ON public.appointment_no_shows(appointment_id); CREATE INDEX IF NOT EXISTS idx_no_shows_flagged_at ON public.appointment_no_shows(flagged_at); CREATE INDEX IF NOT EXISTS idx_no_shows_reason_code ON public.appointment_no_shows(reason_code); CREATE POLICY "Hospital staff can view no-shows" ON public.appointment_no_shows FOR SELECT USING ( hospital_id IN (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid()) ); CREATE POLICY "Hospital staff can create no-shows" ON public.appointment_no_shows FOR INSERT WITH CHECK ( hospital_id IN (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid()) ); CREATE POLICY "Hospital staff can update no-shows" ON public.appointment_no_shows FOR UPDATE USING ( hospital_id IN (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid()) ) WITH CHECK ( hospital_id IN (SELECT hospital_id FROM public.profiles WHERE user_id = auth.uid()) ); GRANT SELECT, INSERT, UPDATE, DELETE ON public.appointment_recurrence_patterns TO authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.appointment_no_shows TO authenticated;